{
  "query": "ACSM exercise warning symptoms stop exercise chest pain dizziness fainting palpitations breathlessness medical care",
  "passages": [
    {
      "id": "acsm-2015-warning-signs#1",
      "document": "ACSM exercise preparticipation health screening and warning signs",
      "section": "Warning signs and symptoms",
      "text": "Exercise-related cardiovascular events are often preceded by warning signs or symptoms. Signs and symptoms suggestive of cardiovascular, metabolic or renal disease include, at rest or during activity: pain or discomfort in the chest, neck, jaw, arms or other areas that may result from ischaemia; shortness of breath at rest or with mild exertion; dizziness or fainting; orthopnea or paroxysmal nocturnal dyspnea; ankle swelling; palpitations or a rapid heartbeat; intermittent claudication (leg pain on walking that eases with rest); a known heart murmur; or unusual fatigue or shortness of breath with usual activities.",
      "publisher": "American College of Sports Medicine",
      "citation": "Riebe D et al. Updating ACSM's Recommendations for Exercise Preparticipation Health Screening. Med Sci Sports Exerc 2015;47(11):2473-2479. PMID 26473759",
      "url": "https://pubmed.ncbi.nlm.nih.gov/26473759/",
      "score": 17.53,
      "card_id": "8dc2c4a8-e22"
    },
    {
      "id": "acsm-2015-warning-signs#2",
      "document": "ACSM exercise preparticipation health screening and warning signs",
      "section": "What to do when symptoms appear",
      "text": "Under the screening algorithm, a physically active person who develops signs or symptoms of cardiovascular, metabolic or renal disease should discontinue exercise and seek medical clearance before resuming exercise of any intensity. A physically inactive person with such signs or symptoms should seek medical clearance before starting an exercise program, regardless of the intensity.",
      "publisher": "American College of Sports Medicine",
      "citation": "Riebe D et al. Updating ACSM's Recommendations for Exercise Preparticipation Health Screening. Med Sci Sports Exerc 2015;47(11):2473-2479. PMID 26473759",
      "url": "https://pubmed.ncbi.nlm.nih.gov/26473759/",
      "score": 9.17,
      "card_id": "8dc2c4a8-e23"
    }
  ],
  "note": "General guidance only; relate it to this person's records or words before using it.",
